import { useEffect, useState } from "react";
import { useSearchParams, useLocation, useNavigate } from "react-router-dom";
import { PageShell } from "../../index.js";
import { useTranslation } from "../../../i18n/I18nProvider.js";
import { CtIcon } from "../../icons/CtIcon.jsx";
import LedgerAssetsView from "../ledger/LedgerAssetsView.jsx";
import LedgerLiabilitiesView from "../ledger/LedgerLiabilitiesView.jsx";
import LedgerInstrumentsView from "../ledger/LedgerInstrumentsView.jsx";

const TABS = [
  { id: "assets", labelKey: "ledger.tab.assets", tone: "asset" },
  { id: "liabilities", labelKey: "ledger.tab.liabilities", tone: "liability" },
  { id: "instruments", labelKey: "ledger.tab.instruments", tone: "instrument" },
];

/** Ledger — assets, liabilities, and instruments in one scrollable shell. */
export default function LedgerPage() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();
  const [searchParams, setSearchParams] = useSearchParams();
  const tabParam = searchParams.get("tab");
  const [tab, setTab] = useState(
    TABS.some((x) => x.id === tabParam) ? tabParam : "assets",
  );

  useEffect(() => {
    const tabFromState = location.state?.tab;
    if (tabFromState && TABS.some((x) => x.id === tabFromState)) {
      setTab(tabFromState);
      setSearchParams({ tab: tabFromState }, { replace: true });
    }
  }, [location.state?.tab, setSearchParams]);

  const openAddOnMount = Boolean(location.state?.openAdd);

  useEffect(() => {
    if (tabParam && TABS.some((x) => x.id === tabParam) && tabParam !== tab) {
      setTab(tabParam);
    }
  }, [tabParam, tab]);

  const switchTab = (id) => {
    setTab(id);
    setSearchParams({ tab: id }, { replace: true });
  };

  const insightsAction = (
    <button
      type="button"
      className="ct-btn ct-btn-ghost ct-btn-sm"
      onClick={() => navigate("/money/wealth")}
    >
      <CtIcon name="chart-bar" size={15} />
      {t("ledger.insightsBtn")}
    </button>
  );

  return (
    <PageShell title={t("nav.ledger")} action={insightsAction} className="ct-ledger-page">
      <div className="pos-ledger-pill-switcher">
        {TABS.map((item) => (
          <button
            key={item.id}
            type="button"
            className={`pos-ledger-pill ${tab === item.id ? `active ${item.tone}` : ""}`}
            onClick={() => switchTab(item.id)}
          >
            {t(item.labelKey)}
          </button>
        ))}
      </div>

      <div key={tab} className="ct-money-tab-fade">
        {tab === "assets" && <LedgerAssetsView openAddOnMount={openAddOnMount && tab === "assets"} />}
        {tab === "liabilities" && <LedgerLiabilitiesView openAddOnMount={openAddOnMount && tab === "liabilities"} />}
        {tab === "instruments" && <LedgerInstrumentsView openAddOnMount={openAddOnMount && tab === "instruments"} />}
      </div>
    </PageShell>
  );
}

